CREATE TABLE IF NOT EXISTS public_schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public_snapshots(id TEXT PRIMARY KEY, imported_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS geographic_units(id TEXT PRIMARY KEY, source_id TEXT, name TEXT NOT NULL, resolution TEXT NOT NULL, reference_year INTEGER, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, name TEXT NOT NULL, geometry TEXT, administrative_area TEXT, source TEXT NOT NULL, source_date TEXT, data_completeness REAL NOT NULL DEFAULT 0, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS indicator_observations(id TEXT PRIMARY KEY, settlement_id TEXT REFERENCES settlements(id), geographic_unit_id TEXT REFERENCES geographic_units(id), indicator_type TEXT NOT NULL, value REAL, unit TEXT NOT NULL, reference_year INTEGER NOT NULL, observation_date TEXT, geographic_resolution TEXT NOT NULL, source TEXT NOT NULL, verification_status TEXT NOT NULL, body TEXT NOT NULL, CHECK ((settlement_id IS NULL) <> (geographic_unit_id IS NULL)));
CREATE INDEX IF NOT EXISTS indicators_settlement ON indicator_observations(settlement_id, indicator_type, observation_date);
CREATE TABLE IF NOT EXISTS redevelopment_projects(id TEXT PRIMARY KEY, source_id TEXT, settlement_id TEXT REFERENCES settlements(id), scheme_name TEXT NOT NULL, project_status TEXT NOT NULL, source_date TEXT, source_url TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS spatial_features(id TEXT PRIMARY KEY, category TEXT NOT NULL, minx REAL NOT NULL, miny REAL NOT NULL, maxx REAL NOT NULL, maxy REAL NOT NULL, body TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS spatial_category ON spatial_features(category);
CREATE TABLE IF NOT EXISTS interventions(id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlements(id), intervention_type TEXT NOT NULL, description TEXT NOT NULL, planned_start TEXT NOT NULL, planned_end TEXT NOT NULL, estimated_cost REAL, status TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inspection_evidence(id TEXT PRIMARY KEY, intervention_id TEXT NOT NULL REFERENCES interventions(id), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS verification_records(id TEXT PRIMARY KEY, intervention_id TEXT NOT NULL REFERENCES interventions(id), verification_type TEXT NOT NULL, recorded_at TEXT NOT NULL, evidence_reference TEXT NOT NULL REFERENCES inspection_evidence(id), outcome TEXT NOT NULL, verifier_reference TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_complaints(id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlements(id), intervention_id TEXT REFERENCES interventions(id), service_type TEXT NOT NULL, description TEXT NOT NULL, reported_at TEXT NOT NULL, status TEXT NOT NULL, resolution_details TEXT, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS field_surveys(id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlements(id), observed_at TEXT NOT NULL, body TEXT NOT NULL);
